1	import { renewalCharge, type PricedServer, type RenewalPrices } from "./renewal-charge";
2	import { monthlyCents } from "./admin-metrics";
3	import type { DunningConfig } from "./dunning-config";
4	
5	/**
6	 * What the admin server fleet list (`/admin/servers`) and server detail page
7	 * need beyond MRR: the REAL per-row renewal price (including add-ons and any
8	 * grandfathered override), and small scannable lifecycle tags. Pulled out as
9	 * pure functions — no DB access — so both the page and a test can call them
10	 * directly against plain objects.
11	 */
12	
13	/**
14	 * A row's real renewal price, monthly-equivalent, INCLUDING add-ons and any
15	 * `grandfatheredRenewalCents` override — priced through `renewalCharge`, the
16	 * one shared formula, not a second copy of it.
17	 *
18	 * Deliberately does NOT zero out for SUSPENDED/DELETING the way
19	 * `serverMonthlyCents` (current MRR contribution) does — that zero is correct
20	 * for "how much revenue is this server generating right now" but wrong for a
21	 * fleet-list PRICE column, where an admin looking at a suspended-unpaid row
22	 * needs to see what it actually costs (paired with the "Overdue" tag
23	 * explaining why it isn't being collected), not a $0.00 that reads as "this
24	 * customer owes nothing".
25	 */
26	export function serverFleetPriceCents(s: PricedServer, prices: RenewalPrices): number {
27	  const charge = renewalCharge(s, prices);
28	  return monthlyCents(charge.netCents, charge.months);
29	}
30	
31	export type FleetTagTone = "brand" | "green" | "red" | "amber" | "slate";
32	export type FleetTag = { key: string; tone: FleetTagTone; label: string; title?: string };
33	
34	/** The columns a fleet-list row needs to derive its lifecycle/add-on tags. */
35	export type FleetTagServer = {
36	  status: string;
37	  isFree: boolean;
38	  expiresAt: Date | null;
39	  suspendReason: string | null;
40	  grandfatheredRenewalCents: number | null;
41	  extraDiskGB: number;
42	  backupTier: string;
43	  wantsDedicatedIp: boolean;
44	  dedicatedIp: unknown | null;
45	  // Needed ONLY to tell an actually-frozen-below-market rate apart from the
46	  // routine "freeze the rate you were sold at" write every order/resize makes
47	  // (lib/order.ts, lib/game-order.ts, worker/index.ts) — that write sets
48	  // grandfatheredRenewalCents on basically every server, so a plain `!= null`
49	  // check tagged nearly the whole fleet "Grandfathered", including brand-new
50	  // customers on today's live pricing (caught 2026-09-25: the owner screenshotted
51	  // the fleet list and pointed out most rows tagged weren't actually on old
52	  // pricing). Mirrors app/admin/servers/[id]/page.tsx's own
53	  // effectivePlanMonthlyCents-vs-livePlanMonthlyCents comparison exactly.
54	  plan: { priceCents: number };
55	  gamePlan: { priceCents: number; termMonths: number } | null;
56	};
57	
58	/**
59	 * Small, scannable per-server tags for the fleet list. Every condition is
60	 * lifted from an existing, real definition elsewhere in the codebase rather
61	 * than invented fresh here — see each branch's comment for where it comes
62	 * from — so a tag can never disagree with the mechanism it describes.
63	 */
64	export function serverFleetTags(
65	  s: FleetTagServer,
66	  opts: {
67	    now: Date;
68	    /** "Renewing soon" window, in ms. Reuse an existing convention — see caller. */
69	    renewingSoonWindowMs: number;
70	    /**
71	     * The real dunning config (lib/dunning-config.ts — the exact function
72	     * worker/billing.ts's sweep uses), or null to skip the "Deleting soon"
73	     * computation entirely (e.g. the caller already knows no suspended-unpaid
74	     * rows exist and didn't bother fetching it).
75	     */
76	    dunning: DunningConfig | null;
77	  },
78	): FleetTag[] {
79	  const tags: FleetTag[] = [];
80	  const nowMs = opts.now.getTime();
81	
82	  if (s.grandfatheredRenewalCents != null) {
83	    const livePlanMonthlyCents = s.gamePlan
84	      ? monthlyCents(s.gamePlan.priceCents, s.gamePlan.termMonths)
85	      : s.plan.priceCents;
86	    const effectivePlanMonthlyCents = s.gamePlan
87	      ? monthlyCents(s.grandfatheredRenewalCents, s.gamePlan.termMonths)
88	      : s.grandfatheredRenewalCents;
89	    if (effectivePlanMonthlyCents !== livePlanMonthlyCents) {
90	      tags.push({ key: "grandfathered", tone: "brand", label: "Grandfathered" });
91	    }
92	  }
93	  if (s.extraDiskGB > 0) {
94	    tags.push({ key: "disk", tone: "slate", label: `+${s.extraDiskGB} GB disk` });
95	  }
96	  if (s.backupTier === "PLUS") {
97	    tags.push({ key: "backup", tone: "slate", label: "Backup Plus" });
98	  }
99	  // Billable IP only (dedicatedIp present AND wantsDedicatedIp) — matches
100	  // renewalCharge's own `dedicatedIpBillable` gate exactly (lib/renewal-charge.ts),
101	  // so this tag never claims a surcharge for a free platform-default IP perk.
102	  if (s.dedicatedIp && s.wantsDedicatedIp) {
103	    tags.push({ key: "ip", tone: "slate", label: "Dedicated IP" });
104	  }
105	
106	  // OVERDUE. Two real states worker/billing.ts itself already distinguishes —
107	  // lifted directly from its own queries, not reinvented:
108	  //  1. Suspended for nonpayment: exactly `terminateOverdue`'s own where-clause
109	  //     (status SUSPENDED, suspendReason UNPAID) — worker/billing.ts's one real
110	  //     definition of "overdue and suspended for it".
111	  //  2. Expired but not yet suspended (still mid-dunning or awaiting the sweep's
112	  //     first attempt): exactly `dueServers()`'s own where-clause (expired,
113	  //     status RUNNING/STOPPED) — the sweep's own definition of "due".
114	  const suspendedUnpaid = s.status === "SUSPENDED" && s.suspendReason === "UNPAID";
115	  const expiredNotYetSuspended =
116	    !s.isFree && s.expiresAt != null && s.expiresAt.getTime() < nowMs && (s.status === "RUNNING" || s.status === "STOPPED");
117	  const overdue = suspendedUnpaid || expiredNotYetSuspended;
118	
119	  // DELETING SOON. Only the suspended-unpaid branch of "overdue" ever gets
120	  // terminated — mirrors terminateOverdue's own `warnAt`/`terminateAt` window
121	  // exactly (lib/dunning-config.ts's `dunningConfig()`, the same function the
122	  // real sweep calls). Strictly a subset of `overdue`, so it REPLACES the
123	  // "Overdue" tag rather than adding a second red pill that says less.
124	  let deletingSoon = false;
125	  let terminateAtDate: Date | null = null;
126	  if (suspendedUnpaid && s.expiresAt && opts.dunning && opts.dunning.autoSuspend) {
127	    const DAY_MS = 86_400_000;
128	    const warnAt = s.expiresAt.getTime() + opts.dunning.warnDays * DAY_MS;
129	    terminateAtDate = new Date(s.expiresAt.getTime() + opts.dunning.terminateDays * DAY_MS);
130	    if (nowMs >= warnAt) deletingSoon = true;
131	  }
132	
133	  if (deletingSoon) {
134	    tags.push({
135	      key: "deleting",
136	      tone: "red",
137	      label: "Deleting soon",
138	      title: terminateAtDate
139	        ? `Unpaid since ${s.expiresAt!.toISOString().slice(0, 10)} — scheduled for deletion around ${terminateAtDate.toISOString().slice(0, 10)} if it stays unpaid`
140	        : undefined,
141	    });
142	  } else if (overdue) {
143	    tags.push({ key: "overdue", tone: "red", label: "Overdue" });
144	  } else {
145	    // RENEWING SOON — only meaningful when not already overdue/suspended/deleting
146	    // (an overdue server is not "renewing soon", it already failed to renew).
147	    // Mirrors app/admin/servers/page.tsx's own "expiring soon" alert filter.
148	    const renewingSoon =
149	      !s.isFree &&
150	      s.status !== "SUSPENDED" &&
151	      s.status !== "DELETING" &&
152	      s.expiresAt != null &&
153	      s.expiresAt.getTime() >= nowMs &&
154	      s.expiresAt.getTime() <= nowMs + opts.renewingSoonWindowMs;
155	    if (renewingSoon) tags.push({ key: "renewing_soon", tone: "amber", label: "Renewing soon" });
156	  }
157	
158	  return tags;
159	}
