1312	export async function adminSetServerFree(serverId: string, isFree: boolean) {
1313	  const admin = await requireAdmin();
1314	  await db.server.update({
1315	    where: { id: serverId },
1316	    data: {
1317	      isFree,
1318	      expiresAt: isFree ? null : new Date(Date.now() + 30 * 86400_000),
1319	      // Same integrity problem as adminExtendServer, and the same answer: taking a
1320	      // server OFF free hands it a 30-day term nobody paid for, so record the whole
1321	      // window as gifted (100% off) and no proration can pay it out. Not blended —
1322	      // this REPLACES `expiresAt` outright rather than extending it, so there are no
