1	/**
2	 * Resolve existing Server.hostname duplicates BEFORE the `@unique` constraint
3	 * (prisma/schema.prisma) can be applied via `npx prisma db push` — Postgres
4	 * will refuse to add a unique index while duplicate values exist.
5	 *
6	 * Strategy (per normalized-hostname duplicate group): the OLDEST server (by
7	 * createdAt) keeps its name unchanged; every newer duplicate in the group is
8	 * renamed to `<name>-<short suffix>`, picking a suffix that collides with
9	 * neither another existing hostname nor another rename this same run is about
10	 * to make. Nothing is renamed across groups — only within a group that
11	 * actually collides.
12	 *
13	 * This is a CUSTOMER-VISIBLE change (their server's hostname appears in their
14	 * dashboard and in DNS/vhost contexts for anyone using a custom domain), so it
15	 * is a deliberate, explicit, reviewable script — NOT a migration side effect:
16	 *
17	 *   npx tsx scripts/dedupe-hostnames.ts             # dry run — prints the plan, changes nothing
18	 *   npx tsx scripts/dedupe-hostnames.ts --apply      # actually renames, one server.update per row
19	 *
20	 * Each rename is logged to AuditLog (action "admin.hostname_dedupe") so it
21	 * shows up in the admin Activity screen like any other server change.
22	 *
23	 * Safe to re-run: a dry run never writes, and --apply re-checks each row's
24	 * CURRENT hostname immediately before writing (skips it if something else
25	 * already resolved the collision since the plan was built).
26	 */
27	import { db } from "../lib/db";
28	import { randHostnameSuffix } from "../lib/hostname";
29	
30	const APPLY = process.argv.includes("--apply");
31	
32	async function main() {
33	  const servers = await db.server.findMany({
34	    select: { id: true, hostname: true, status: true, vmid: true, createdAt: true, user: { select: { email: true } } },
35	    orderBy: { createdAt: "asc" },
36	  });
37	
38	  const allHostnames = new Set(servers.map((s) => s.hostname.trim().toLowerCase()));
39	
40	  const groups = new Map<string, typeof servers>();
41	  for (const s of servers) {
42	    const norm = s.hostname.trim().toLowerCase();
43	    const g = groups.get(norm);
44	    if (g) g.push(s);
45	    else groups.set(norm, [s]);
46	  }
47	
48	  const dupeGroups = [...groups.entries()].filter(([, rows]) => rows.length > 1);
49	  if (dupeGroups.length === 0) {
50	    console.log("No duplicate hostnames found — nothing to do.");
51	    process.exit(0);
52	  }
53	
54	  type Plan = { id: string; owner: string; from: string; to: string };
55	  const plan: Plan[] = [];
56	
57	  for (const [norm, rows] of dupeGroups) {
58	    // Rows are already createdAt-ascending (the query's orderBy) — keep the
59	    // first (oldest) untouched, rename every later duplicate.
60	    const [keeper, ...rest] = rows;
61	    console.log(`Group "${norm}": keeping ${keeper.id} (owner ${keeper.user.email}, oldest, created ${keeper.createdAt.toISOString()}) unchanged.`);
62	    for (const dupe of rest) {
63	      let candidate = "";
64	      for (let attempt = 0; attempt < 8; attempt++) {
65	        const c = `${norm}-${randHostnameSuffix(4)}`;
66	        if (!allHostnames.has(c)) {
67	          candidate = c;
68	          break;
69	        }
70	      }
71	      if (!candidate) candidate = `${norm}-${Date.now().toString(36)}`;
72	      allHostnames.add(candidate); // reserve it so a later dupe in this run can't pick the same one
73	      plan.push({ id: dupe.id, owner: dupe.user.email, from: dupe.hostname, to: candidate });
74	    }
75	  }
76	
77	  console.log(`\n${APPLY ? "Applying" : "Planned (dry run)"} ${plan.length} rename(s):\n`);
78	  for (const p of plan) {
79	    console.log(`  id=${p.id}  owner=${p.owner}  "${p.from}" -> "${p.to}"`);
80	  }
81	
82	  if (!APPLY) {
83	    console.log("\nDry run only — nothing was changed. Re-run with --apply to write these renames.");
84	    process.exit(0);
85	  }
86	
87	  console.log("");
88	  let done = 0;
89	  for (const p of plan) {
90	    // Re-check immediately before writing — cheap insurance against this
91	    // script running twice concurrently, or a row changing hostname between
92	    // the plan being built and applied.
93	    const current = await db.server.findUnique({ where: { id: p.id }, select: { hostname: true } });
94	    if (!current || current.hostname !== p.from) {
95	      console.log(`  [skip] ${p.id} — hostname changed since the plan was built (now "${current?.hostname ?? "(deleted)"}").`);
96	      continue;
97	    }
98	    try {
99	      await db.server.update({ where: { id: p.id }, data: { hostname: p.to } });
100	      await db.auditLog.create({
101	        data: {
102	          userId: null,
103	          action: "admin.hostname_dedupe",
104	          detail: `${p.id} (owner ${p.owner}) "${p.from}" -> "${p.to}" — pre-existing duplicate resolved before Server.hostname @unique was applied`,
105	          category: "server",
106	        },
107	      });
108	      console.log(`  [ ok ] ${p.id} — "${p.from}" -> "${p.to}"`);
109	      done++;
110	    } catch (e) {
111	      console.error(`  [FAIL] ${p.id} — ${(e as Error)?.message ?? e}`);
112	    }
113	  }
114	  console.log(`\nDone: ${done}/${plan.length} renamed.`);
115	  if (done < plan.length) process.exit(1);
116	}
117	
118	main().catch((e) => {
119	  console.error(e);
120	  process.exit(2);
121	});
