47	    process.exit(0);
48	  }
49	
50	  console.log(`${dupes.length} duplicate hostname group(s):\n`);
51	  for (const [norm, rows] of dupes) {
52	    console.log(`  "${norm}" — ${rows.length} servers:`);
53	    for (const r of rows) {
54	      console.log(
55	        `    id=${r.id}  owner=${r.user.email}  status=${r.status}  vmid=${r.vmid ?? "-"}  created=${r.createdAt.toISOString()}` +
56	          (r.hostname !== norm ? `  (stored as "${r.hostname}")` : ""),
57	      );
58	    }
59	    console.log("");
60	  }
61	
62	  console.log("Run scripts/dedupe-hostnames.ts (dry run first) before applying the @unique constraint.");
