 * Separately verified: the very first WalletTransaction line for a GAME
 * server order (lib/game-order.ts, `Game server: <plan> (<family>) — <term>`)
 * omits the hostname — unlike every sibling call site. It doesn't normally
 * matter here (Invoice is primary and DOES carry the hostname for that same
 * charge, since commit 5ecc6eedf4 "Create an Invoice + invoice-new email for
 * game-server orders", 2026-08-27) — but any game server ordered BEFORE that
 * commit has NO invoice at all, only that hostname-less WalletTransaction
 * debit, and would otherwise show $0 lifetime spend despite having genuinely
 * paid. Verified against production: exactly this happened to one live
 * customer server (terraria-i2ydef, ordered 2026-08-26). Recovered below via
 * a time-proximity fallback (same owner, a "Game server:" debit within 60s of
 * the server's own `createdAt` — the two rows are written in the same
 * transaction, so in practice they land within a couple of milliseconds of
 * each other) ONLY when no invoice at all matched this server's hostname, so
 * a normal (post-fix) order is never double-counted.
 */
export async function resolveServerLifetimeSpendCents(
  servers: { id: string; hostname: string; userId: string; createdAt: Date }[],
): Promise<Map<string, number>> {
  const result = new Map<string, number>();
  if (servers.length === 0) return result;

  const userIds = Array.from(new Set(servers.map((s) => s.userId)));

  const [invoices, corrections, preInvoiceGameOrders] = await Promise.all([
    db.invoice.findMany({
      where: { userId: { in: userIds }, status: { in: ["PAID", "REFUNDED"] } },
      select: { userId: true, description: true, amountCents: true, refundedCents: true, status: true },
    }),
    db.walletTransaction.findMany({
      where: {
        userId: { in: userIds },
        OR: [
          { description: { startsWith: "Downgrade to" } },
          { description: { startsWith: "Refund: failed" } },
          { description: { startsWith: "Reversed downgrade credit" } },
        ],
      },
      select: { userId: true, description: true, amountCents: true },
    }),
    // Fallback pool for the pre-5ecc6eedf4 (2026-08-27) gap documented above:
    // game-order debits that never got an invoice and don't carry a hostname.
    db.walletTransaction.findMany({
      where: { userId: { in: userIds }, description: { startsWith: "Game server:" }, amountCents: { lt: 0 } },
      select: { userId: true, amountCents: true, createdAt: true },
    }),
  ]);

  for (const s of servers) {
    let cents = 0;
    let anyInvoiceMatched = false;

    for (const inv of invoices) {
      if (inv.userId !== s.userId || !inv.description.includes(s.hostname)) continue;
      anyInvoiceMatched = true;
      if (inv.status === "PAID") {
        cents += inv.amountCents - (inv.refundedCents ?? 0);
      } else if (inv.status === "REFUNDED") {
        // A standalone credit-note invoice (e.g. "Cancellation refund — host")
        // — its amountCents is the positive amount returned to the customer.
        cents -= inv.amountCents;
      }
    }

    for (const c of corrections) {
      if (c.userId !== s.userId || !c.description.includes(s.hostname)) continue;
      // amountCents > 0 (Downgrade credit, failed-job refund) reduces spend;
      // amountCents < 0 (a clawed-back downgrade credit) restores it.
      cents -= c.amountCents;
    }

