1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { serverFleetPriceCents, serverFleetTags, type FleetTagServer } from "../lib/admin-fleet.ts";
4	import type { PricedServer, RenewalPrices } from "../lib/renewal-charge.ts";
5	import type { DunningConfig } from "../lib/dunning-config.ts";
6	
7	/**
8	 * Guards for the /admin/servers fleet list's Price column and lifecycle tags
9	 * (lib/admin-fleet.ts). This is the surface built to fix the real live bug the
10	 * owner found on darkeden-guard-sg: the list showed the bare plan price, with
11	 * no awareness of add-ons or a per-server grandfathered rate.
12	 *
13	 * `serverFleetPriceCents` is a thin wrapper over `renewalCharge` — the same
14	 * pricing formula worker/billing.ts, the saved-card path and "Renew now" all
15	 * charge through — so the grandfather-survives-a-price-rise and
16	 * unaffected-when-unset guarantees are already proven at the `renewalCharge`
17	 * level in test/money-core-guards.test.ts. What's specific to THIS file is:
18	 * the fleet list actually calls through to that guarantee, includes add-ons,
19	 * and (deliberately, unlike MRR's serverMonthlyCents) does not zero out for a
20	 * suspended row — plus the tag logic, which is new.
21	 */
22	
23	const PRICES: RenewalPrices = { ipMonthlyCents: 299, extraDiskPerGbCents: 100, backupPlusCents: 199, annualDiscountPct: 0 };
24	
25	function vps(overrides: Partial<PricedServer> = {}): PricedServer {
26	  return {
27	    termMonths: 1,
28	    extraDiskGB: 0,
29	    plan: { name: "Starter", priceCents: 899 },
30	    gamePlan: null,
31	    dedicatedIp: null,
32	    wantsDedicatedIp: false,
33	    backupTier: "FREE",
34	    ...overrides,
35	  };
36	}
37	
38	test("serverFleetPriceCents: a grandfathered server shows its locked price, not the live plan price", () => {
39	  const s = vps({ plan: { name: "Starter", priceCents: 1619 }, grandfatheredRenewalCents: 899 });
40	  assert.equal(serverFleetPriceCents(s, PRICES), 899, "must show the frozen rate, not the raised live price");
41	});
42	
43	test("serverFleetPriceCents: a non-grandfathered server is completely unaffected", () => {
44	  const s = vps({ plan: { name: "Starter", priceCents: 899 } });
45	  assert.equal(serverFleetPriceCents(s, PRICES), 899);
46	});
47	
48	test("serverFleetPriceCents: the locked price survives whatever the live plan does later, alongside add-ons", () => {
49	  // The live plan price triples AND the customer has real add-ons — the locked
50	  // base must still win, and the add-on lines must still be added on top of it,
51	  // exactly like renewalCharge composes them for every other caller.
52	  const s = vps({
53	    plan: { name: "Starter", priceCents: 2699 }, // tripled since sale
54	    extraDiskGB: 20,
55	    backupTier: "PLUS",
56	    dedicatedIp: { id: "ip1" },
57	    wantsDedicatedIp: true,
58	    grandfatheredRenewalCents: 899,
59	  });
60	  const expected = 899 + 20 * 100 + 199 + 299; // locked base + disk + backup + IP
61	  assert.equal(serverFleetPriceCents(s, PRICES), expected);
62	});
63	
64	test("serverFleetPriceCents: a free platform-default IP is never billed, grandfathered or not", () => {
65	  const s = vps({ dedicatedIp: { id: "ip1" }, wantsDedicatedIp: false, grandfatheredRenewalCents: 899 });
66	  assert.equal(serverFleetPriceCents(s, PRICES), 899);
67	});
68	
69	test("serverFleetPriceCents: unlike MRR's serverMonthlyCents, a suspended row still shows its real price", () => {
70	  // MRR correctly zeroes a suspended server (it isn't being collected right
71	  // now). The fleet PRICE column is a different question — "what does this
72	  // server cost" — and must keep showing the real number so it can sit next to
73	  // the "Overdue" tag instead of a misleading $0.00.
74	  const s = vps({ plan: { name: "Starter", priceCents: 899 } });
75	  assert.equal(serverFleetPriceCents(s, PRICES), 899);
76	});
77	
78	/* ------------------------------------------------------------------ *
79	 * Tags
80	 * ------------------------------------------------------------------ */
81	
82	const DUNNING: DunningConfig = { graceDays: 3, warnDays: 7, terminateDays: 14, autoSuspend: true };
83	const DAY = 86_400_000;
84	const NOW = new Date("2026-09-25T00:00:00.000Z");
85	
86	function server(overrides: Partial<FleetTagServer> = {}): FleetTagServer {
87	  return {
88	    status: "RUNNING",
89	    isFree: false,
90	    expiresAt: null,
91	    suspendReason: null,
92	    grandfatheredRenewalCents: null,
93	    extraDiskGB: 0,
94	    backupTier: "FREE",
95	    wantsDedicatedIp: false,
96	    dedicatedIp: null,
97	    plan: { priceCents: 899 },
98	    gamePlan: null,
99	    ...overrides,
100	  };
101	}
102	
103	const tagKeys = (s: FleetTagServer, opts: { dunning?: DunningConfig | null } = {}) =>
104	  serverFleetTags(s, { now: NOW, renewingSoonWindowMs: 5 * DAY, dunning: opts.dunning ?? null }).map((t) => t.key);
105	
106	test("tags: Grandfathered shows only when the locked rate actually diverges from the live plan price", () => {
107	  // Every order/resize freezes grandfatheredRenewalCents as routine behavior
108	  // (lib/order.ts, lib/game-order.ts, worker/index.ts) — a brand-new customer
109	  // on today's live pricing has it set too, equal to the live plan price. A
110	  // bare `!= null` check tagged that customer "Grandfathered" right alongside
111	  // someone actually held at an old, no-longer-offered rate (caught live
112	  // 2026-09-25: the owner's fleet screenshot showed nearly every row tagged).
113	  assert.deepEqual(tagKeys(server({ plan: { priceCents: 899 }, grandfatheredRenewalCents: 899 })), [], "locked rate equals live rate — not actually grandfathered");
114	  assert.deepEqual(tagKeys(server({ plan: { priceCents: 1619 }, grandfatheredRenewalCents: 899 })), ["grandfathered"], "locked rate is below today's live rate — genuinely grandfathered");
115	  assert.deepEqual(tagKeys(server()), []);
116	});
117	
118	test("tags: Grandfathered for a game server compares monthly-equivalent rates, not raw term totals", () => {
119	  const gamePlan = { priceCents: 1699, termMonths: 1 };
120	  assert.deepEqual(
121	    tagKeys(server({ gamePlan, grandfatheredRenewalCents: 1699 })),
122	    [],
123	    "locked rate equals the live game-plan rate",
124	  );
125	  assert.deepEqual(
126	    tagKeys(server({ gamePlan, grandfatheredRenewalCents: 1199 })),
127	    ["grandfathered"],
128	    "locked below today's live game-plan rate",
129	  );
130	});
131	
132	test("tags: one add-on tag per real add-on, derived from real fields", () => {
133	  assert.deepEqual(tagKeys(server({ extraDiskGB: 20 })), ["disk"]);
134	  assert.deepEqual(tagKeys(server({ backupTier: "PLUS" })), ["backup"]);
