test("tags: Grandfathered shows only when the locked rate is BELOW the live plan price — never equal, never above", () => {
  // Every order/resize freezes grandfatheredRenewalCents as routine behavior
  // (lib/order.ts, lib/game-order.ts, worker/index.ts) — a brand-new customer
  // on today's live pricing has it set too, equal to the live plan price. A
  // bare `!= null` check tagged that customer "Grandfathered" right alongside
  // someone actually held at an old, no-longer-offered rate (caught live
  // 2026-09-25: the owner's fleet screenshot showed nearly every row tagged).
  assert.deepEqual(tagKeys(server({ plan: { priceCents: 899 }, grandfatheredRenewalCents: 899 })), [], "locked rate equals live rate — not actually grandfathered");
  assert.deepEqual(tagKeys(server({ plan: { priceCents: 1619 }, grandfatheredRenewalCents: 899 })), ["grandfathered"], "locked rate is below today's live rate — genuinely grandfathered, favorable to the customer");
  // DIRECTION MATTERS: "Grandfathered" is a favorable-to-the-customer claim
  // (protection from a price INCREASE), never a customer stuck paying MORE
  // than today's live rate. Caught live 2026-09-25 — the owner's own words,
  // "we dont qualify them for the grandfathered pricing" — on two real
  // servers (web-01-oyrj, minecraft-qj4rxt) locked ABOVE live after an
  // across-the-board 20% renewal-price cut. A same-direction bug in
  // `renewalCharge` (lib/renewal-charge.ts) would mean this server is
  // actually being billed the higher locked rate on every real renewal —
  // display and billing are two separate concerns, but the tag must never
  // imply the opposite of what's true.
  assert.deepEqual(tagKeys(server({ plan: { priceCents: 899 }, grandfatheredRenewalCents: 1619 })), [], "locked rate is ABOVE today's live rate — not favorable, must not say Grandfathered");
  assert.deepEqual(tagKeys(server()), []);
});

