/**
 * ONE-TIME backfill: populate `Server.previousHostnames` for the 6 servers
 * renamed by `scripts/dedupe-hostnames.ts`'s real 2026-09-24 run, so their
 * pre-rename Invoice/WalletTransaction rows (which still say "web-01" in
 * their `description`, not the new suffixed name) match again in
 * `resolveServerLifetimeSpendCents` (lib/server-spend.ts) and
 * `regenerateMissingInvoices` (lib/actions-billing.ts).
 *
 * REQUIRES the `Server.previousHostnames String[] @default([])` column
 * (prisma/schema.prisma) to already exist in the target database — run
 * `npx prisma db push` first.
 *
 * The exact id -> old-hostname mapping below is copied verbatim from the
 * real AuditLog rows this dedupe run itself wrote (action
 * "admin.hostname_dedupe", 2026-09-24 12:19:21 UTC) — read, not guessed:
 *
 *   cmu2olq840001hllu2we7hkop  "web-01" -> "web-01-npto"
 *   cmu2p64ce006fhlnoev60c0ds  "web-01" -> "web-01-q1uw"
 *   cmu3tci1r1g1qhl6oqinuvays  "web-01" -> "web-01-n6kl"
 *   cmu3uc3gw1h98hl6obh28mwg8  "web-01" -> "web-01-aelb"
 *   cmu5yv2gn0cjlhluhzj0oxbth  "web-01" -> "web-01-oyrj"
 *   cmuevsfqn0s6uhl7a5u3vistu  "web-01" -> "web-01-pvm4"
 *
 * Every one of those 6 servers' CURRENT hostname and previousHostnames were
 * re-verified live against the AuditLog + Server tables before this script
 * was written (2026-09-25) — see the fleet-spend-rename-and-grandfathered-
 * direction branch's commit message for the full verification.
 *
 *   npx tsx scripts/backfill-previous-hostnames-2026-09-24-dedupe.ts             # dry run — prints the plan, changes nothing
 *   npx tsx scripts/backfill-previous-hostnames-2026-09-24-dedupe.ts --apply      # actually writes previousHostnames
 *
 * Safe to re-run: --apply re-checks each row's CURRENT hostname and existing
 * previousHostnames immediately before writing, and skips a row that
 * already has the old hostname recorded (so running this twice never
 * double-appends).
 */
import { db } from "../lib/db";

const APPLY = process.argv.includes("--apply");

const PLAN: { id: string; oldHostname: string; expectedCurrentHostname: string }[] = [
  { id: "cmu2olq840001hllu2we7hkop", oldHostname: "web-01", expectedCurrentHostname: "web-01-npto" },
  { id: "cmu2p64ce006fhlnoev60c0ds", oldHostname: "web-01", expectedCurrentHostname: "web-01-q1uw" },
  { id: "cmu3tci1r1g1qhl6oqinuvays", oldHostname: "web-01", expectedCurrentHostname: "web-01-n6kl" },
  { id: "cmu3uc3gw1h98hl6obh28mwg8", oldHostname: "web-01", expectedCurrentHostname: "web-01-aelb" },
  { id: "cmu5yv2gn0cjlhluhzj0oxbth", oldHostname: "web-01", expectedCurrentHostname: "web-01-oyrj" },
  { id: "cmuevsfqn0s6uhl7a5u3vistu", oldHostname: "web-01", expectedCurrentHostname: "web-01-pvm4" },
];

async function main() {
  console.log(`${APPLY ? "Applying" : "Planned (dry run)"} previousHostnames backfill for ${PLAN.length} server(s):\n`);

  let done = 0;
  let skipped = 0;
  for (const row of PLAN) {
    const current = await db.server.findUnique({
      where: { id: row.id },
      select: { hostname: true, previousHostnames: true },
    });
    if (!current) {
      console.log(`  [FAIL] ${row.id} — server no longer exists.`);
      continue;
    }
    if (current.hostname !== row.expectedCurrentHostname) {
      console.log(
        `  [skip] ${row.id} — expected current hostname "${row.expectedCurrentHostname}", found "${current.hostname}" — something else changed it, not touching.`,
      );
      skipped++;
      continue;
    }
    if (current.previousHostnames.includes(row.oldHostname)) {
      console.log(`  [skip] ${row.id} — "${row.oldHostname}" already recorded in previousHostnames.`);
      skipped++;
      continue;
    }

    console.log(`  ${row.id}  hostname="${current.hostname}"  previousHostnames += ["${row.oldHostname}"]`);
    if (APPLY) {
      await db.server.update({
        where: { id: row.id },
        data: { previousHostnames: { push: row.oldHostname } },
      });
      await db.auditLog.create({
        data: {
          userId: null,
          action: "admin.previous_hostname_backfill",
          detail: `${row.id} (${current.hostname}) previousHostnames += "${row.oldHostname}" — restores Invoice/WalletTransaction hostname-substring matching after the 2026-09-24 dedupe rename (see lib/server-spend.ts)`,
          category: "server",
        },
      });
      done++;
    }
  }

  console.log(`\n${APPLY ? `Done: ${done} updated, ${skipped} skipped.` : "Dry run only — nothing was changed. Re-run with --apply to write."}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(2);
  })
  .finally(async () => {
    await db.$disconnect();
  });

