      console.log(`  [FAIL] ${row.id} — server no longer exists.`);
      continue;
    }
    if (current.hostname !== row.expectedCurrentHostname) {
      console.log(
        `  [skip] ${row.id} — expected current hostname "${row.expectedCurrentHostname}", found "${current.hostname}" — something else changed it, not touching.`,
      );
      skipped++;
      continue;
    }
    if (current.previousHostnames.includes(row.oldHostname)) {
      console.log(`  [skip] ${row.id} — "${row.oldHostname}" already recorded in previousHostnames.`);
      skipped++;
      continue;
    }

    console.log(`  ${row.id}  hostname="${current.hostname}"  previousHostnames += ["${row.oldHostname}"]`);
    if (APPLY) {
      await db.server.update({
        where: { id: row.id },
        data: { previousHostnames: { push: row.oldHostname } },
      });
      await db.auditLog.create({
        data: {
          userId: null,
          action: "admin.previous_hostname_backfill",
          detail: `${row.id} (${current.hostname}) previousHostnames += "${row.oldHostname}" — restores Invoice/WalletTransaction hostname-substring matching after the 2026-09-24 dedupe rename (see lib/server-spend.ts)`,
          category: "server",
        },
      });
      done++;
    }
  }

  console.log(`\n${APPLY ? `Done: ${done} updated, ${skipped} skipped.` : "Dry run only — nothing was changed. Re-run with --apply to write."}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(2);
  })
  .finally(async () => {
    await db.$disconnect();
  });

