/**
 * READ-ONLY verification: proves the resolveServerLifetimeSpendCents fix is
 * correct against REAL production invoice data, without requiring the
 * previousHostnames column to exist yet (the real prod DB schema push is
 * blocked pending owner/operator approval — see the branch's commit
 * message). Simulates the post-backfill state by passing previousHostnames
 * straight into the function call (it's a plain input parameter, not a DB
 * read), so this exercises the exact same code path the real column will
 * once it's populated.
 */
import { db } from "../lib/db";
import { resolveServerLifetimeSpendCents } from "../lib/server-spend";

const SIX = [
  { id: "cmu2olq840001hllu2we7hkop", hostname: "web-01-npto" },
  { id: "cmu2p64ce006fhlnoev60c0ds", hostname: "web-01-q1uw" },
  { id: "cmu3tci1r1g1qhl6oqinuvays", hostname: "web-01-n6kl" },
  { id: "cmu3uc3gw1h98hl6obh28mwg8", hostname: "web-01-aelb" },
  { id: "cmu5yv2gn0cjlhluhzj0oxbth", hostname: "web-01-oyrj" },
  { id: "cmuevsfqn0s6uhl7a5u3vistu", hostname: "web-01-pvm4" },
];

async function main() {
  const rows = await db.server.findMany({
    where: { id: { in: SIX.map((s) => s.id) } },
    select: { id: true, hostname: true, userId: true, createdAt: true, user: { select: { email: true } } },
  });

  const beforeInput = rows.map((r) => ({ id: r.id, hostname: r.hostname, previousHostnames: [], userId: r.userId, createdAt: r.createdAt }));
  const afterInput = rows.map((r) => ({ id: r.id, hostname: r.hostname, previousHostnames: ["web-01"], userId: r.userId, createdAt: r.createdAt }));

  const before = await resolveServerLifetimeSpendCents(beforeInput);
  const after = await resolveServerLifetimeSpendCents(afterInput);

  console.log("id                          hostname       owner                          BEFORE(no previousHostnames)  AFTER(previousHostnames=['web-01'])");
  for (const r of rows) {
    const b = before.get(r.id) ?? 0;
    const a = after.get(r.id) ?? 0;
    console.log(
      `${r.id}  ${r.hostname.padEnd(13)}  ${r.user.email.padEnd(29)}  $${(b / 100).toFixed(2).padStart(8)}                     $${(a / 100).toFixed(2).padStart(8)}`,
    );
  }
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(2);
  })
  .finally(async () => {
    await db.$disconnect();
  });

